import type { BankQuestion } from "@/lib/bank";

/** Average (Quantitative Aptitude): 143 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"quant-average-1","question":"What is the average of the first 10 natural numbers?","options":["5","5.5","6","10"],"answer":1,"explanation":"Average of 1 to n = (n + 1) / 2 = 11 / 2 = 5.5.","difficulty":"easy"},
  {"id":"quant-average-2","question":"The average of 5 numbers is 20. Their sum is:","options":["4","25","100","120"],"answer":2,"explanation":"Sum = Average × Count = 20 × 5 = 100.","difficulty":"easy"},
  {"id":"quant-average-3","question":"The average of five consecutive odd numbers is 25. The largest of them is:","options":["27","29","31","33"],"answer":1,"explanation":"For consecutive numbers the average is the middle term, 25; the numbers are 21, 23, 25, 27, 29.","difficulty":"moderate"},
  {"id":"quant-average-4","question":"The average weight of 8 people increases by 2.5 kg when a person weighing 65 kg is replaced by a new person. The new person weighs:","options":["75 kg","80 kg","85 kg","90 kg"],"answer":2,"explanation":"Total increase = 8 × 2.5 = 20 kg, so the new person weighs 65 + 20 = 85 kg.","difficulty":"very-hard"},
  {"id":"quant-average-5","question":"The average of the first 10 natural numbers is:","options":["5","5.5","6","10"],"answer":1,"explanation":"Sum = 55; 55/10 = 5.5.","difficulty":"easy","source":"RRB Group D · SSC CHSL"},
  {"id":"quant-average-6","question":"The average of 8 numbers is 20. If each number is multiplied by 3, the new average is:","options":["23","40","60","160"],"answer":2,"explanation":"Multiplying every number by 3 multiplies the average by 3 ⇒ 60.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk"},
  {"id":"quant-average-7","question":"The average weight of 30 students is 40 kg. When the teacher is included the average rises by 1 kg. The teacher’s weight is:","options":["61 kg","66 kg","71 kg","76 kg"],"answer":2,"explanation":"31 × 41 − 30 × 40 = 1,271 − 1,200 = 71 kg.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-average-8","question":"The average of 11 results is 50. The average of the first six is 49 and of the last six is 52. The sixth result is:","options":["50","54","56","58"],"answer":2,"explanation":"6 × 49 + 6 × 52 − 11 × 50 = 294 + 312 − 550 = 56.","difficulty":"very-hard","source":"SSC CGL · SBI Clerk"},
  {"id":"quant-average-9","question":"The average of the first 20 even natural numbers is:","options":["10.5","20","21","22"],"answer":2,"explanation":"The first 20 even numbers are 2, 4, …, 40; average = (2 + 40)/2 = 21.","difficulty":"easy","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-average-10","question":"The average of 7 numbers is 36. When one more number is included, the average becomes 38. The new number is:","options":["38","50","40","52"],"answer":3,"explanation":"Sum rises from 7 × 36 = 252 to 8 × 38 = 304, so the number added = 52.","difficulty":"easy","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-average-11","question":"The average of 10 numbers is 15. Later it is found that one number was read as 36 instead of 63. The correct average is:","options":["12.3","17.7","15.7","18"],"answer":1,"explanation":"The sum was short by 63 − 36 = 27, so the average rises by 27/10 = 2.7 to 17.7.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-average-12","question":"A cricketer has an average of 32 runs after 10 innings. He scores 65 in the 11th innings. His new average is:","options":["34","35","36","33"],"answer":1,"explanation":"New average = (320 + 65)/11 = 385/11 = 35.","difficulty":"moderate","source":"SSC CGL · IBPS PO"},
  {"id":"quant-average-13","question":"The average age of a family of 6 members is 22 years. If the youngest member is 7 years old, what was the average age of the family when the youngest was born?","options":["18 years","22 years","17 years","15 years"],"answer":0,"explanation":"Total now = 132 years. Seven years ago the other 5 members were each 7 years younger: 132 − 7 × 6 = 90 years over 5 members = 18. The 6 × 7 subtraction includes the youngest's 7 years, which removes him entirely.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-average-14","question":"A bus goes from town A to town B at 30 km/h and returns at 20 km/h. Its average speed for the whole journey is:","options":["24 km/h","26 km/h","25 km/h","22 km/h"],"answer":0,"explanation":"Equal distances: average speed = 2 × 30 × 20/(30 + 20) = 1,200/50 = 24 km/h, not the arithmetic mean 25.","difficulty":"moderate","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-average-15","question":"The average of 25 numbers is 50. The average of the first 12 is 48 and of the last 12 is 54. The 13th number is:","options":["25","28","30","26"],"answer":3,"explanation":"Total = 1,250; first 12 sum to 576, last 12 to 648. 13th = 1,250 − 576 − 648 = 26.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-average-16","question":"The average weight of 20 boys is 40 kg. A boy weighing 50 kg leaves and a new boy joins, and the average becomes 39.5 kg. The new boy weighs:","options":["42 kg","45 kg","35 kg","40 kg"],"answer":3,"explanation":"New total = 20 × 39.5 = 790 = 800 − 50 + x, so x = 40 kg.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-average-17","question":"The average monthly salary of the 60 staff of an office is ₹24,000. If the 12 officers average ₹50,000, the average salary of the remaining staff is:","options":["₹20,000","₹18,000","₹17,500","₹16,500"],"answer":2,"explanation":"Total = 60 × 24,000 = ₹14,40,000; officers = ₹6,00,000; the other 48 share ₹8,40,000, an average of ₹17,500.","difficulty":"hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-average-18","question":"The mean of 50 numbers is 38. If two numbers, 45 and 55, are discarded, the mean of the remaining numbers is:","options":["37","37.5","36.5","38"],"answer":1,"explanation":"Sum = 1,900; removing 100 leaves 1,800 over 48 numbers = 37.5.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-average-19","question":"The average of a, b and c is 25 and the average of b, c and d is 30. If d = 45, then a is:","options":["35","15","45","30"],"answer":3,"explanation":"a + b + c = 75 and b + c + d = 90, so d − a = 15 and a = 45 − 15 = 30.","difficulty":"hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-average-20","question":"A batsman scores 87 in his 17th innings and thereby raises his average by 3. His average after the 17th innings is:","options":["38","36","42","39"],"answer":3,"explanation":"If the old average is a: 16a + 87 = 17(a + 3) → a = 36, so the new average is 39.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-average-21","question":"A train covers the first third of a journey at 60 km/h, the second third at 40 km/h and the last third at 30 km/h. Its average speed is:","options":["42 km/h","43⅓ km/h","40 km/h","45 km/h"],"answer":2,"explanation":"Three equal distances d: total time = d/60 + d/40 + d/30 = d(2 + 3 + 4)/120 = 9d/120. Average = 3d ÷ (9d/120) = 40 km/h. 43⅓ is the arithmetic mean, which is wrong for equal distances.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-average-22","question":"The average of 5 numbers is 28. Two of them, 24 and 30, are replaced by two new numbers in the ratio 3 : 5, and the average becomes 30. The larger new number is:","options":["40","48","24","32"],"answer":0,"explanation":"New sum 150 = 140 − 54 + (new pair), so the pair sums to 64. In the ratio 3 : 5 they are 24 and 40; the larger is 40.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-average-23","question":"In a school three sections of 20, 40 and 40 students have average marks of 50, 60 and 70 respectively. The average marks of all 100 students is:","options":["60","63","62","61"],"answer":2,"explanation":"Weighted total = 20 × 50 + 40 × 60 + 40 × 70 = 1,000 + 2,400 + 2,800 = 6,200, average 62. The unweighted mean of 50, 60, 70 (= 60) is wrong.","difficulty":"very-hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-average-24","question":"The average age of the 8 members of a committee is the same today as it was 2 years ago, because one old member has been replaced by a younger one. The new member is younger than the old one by:","options":["8 years","10 years","16 years","2 years"],"answer":2,"explanation":"In 2 years the 8 members aged 16 years in total; for the average to be unchanged, the replacement must remove those 16 years, so the new member is 16 years younger.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-average-25","question":"How many of the following statements are correct?\n1. The average of the first n natural numbers is (n + 1)/2.\n2. If every number in a set is increased by 5, the average increases by 5.\n3. The average of a set of numbers can exceed its largest number.\n4. The average speed of a round trip at speeds u and v is (u + v)/2.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"1 and 2 are true. 3 is false: the average always lies between the smallest and the largest. 4 is false: for equal distances it is 2uv/(u + v). Two statements are correct.","difficulty":"very-hard","source":"SSC CGL · CDS"},
  {"id":"quant-average-26","question":"A hostel mess has 35 students. When 7 more students join, the daily expense rises by ₹42 while the average expense per student falls by ₹1. The original average expense per student was:","options":["₹12","₹13","₹11","₹14"],"answer":0,"explanation":"Let the old average be a: 42(a − 1) = 35a + 42 → 42a − 42 = 35a + 42 → 7a = 84 → a = ₹12.","difficulty":"very-hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-average-27","question":"The average of 50 numbers is 20. If each of the first 25 numbers is increased by 4 and each of the last 25 is decreased by 6, the new average is:","options":["19","20","18","21"],"answer":0,"explanation":"Net change in the sum = 25 × 4 − 25 × 6 = −50, so the average falls by 50/50 = 1 to 19.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-average-28","question":"The average weight of A, B and C is 45 kg. The average of A and B is 40 kg and that of B and C is 43 kg. B's weight is:","options":["35 kg","31 kg","29 kg","40 kg"],"answer":1,"explanation":"A + B + C = 135, A + B = 80, B + C = 86. So C = 55, A = 49 and B = 135 − 55 − 49 = 31 kg.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC"},
  {"id": "quant-average-29", "question": "What is the average of 12, 15, 18, 21 and 24?", "options": ["17", "18", "19", "90"], "answer": 1, "explanation": "Sum = 90, so average = 90 ÷ 5 = 18 (also the middle term of an equally spaced list).", "difficulty": "easy", "source": "RRB NTPC · SSC CHSL"},
  {"id": "quant-average-30", "question": "The average of 6 numbers is 30. The average of the first 4 is 25, and the fifth number is 10 more than the sixth. What is the sixth number?", "options": ["35", "45", "40", "30"], "answer": 0, "explanation": "Total = 180; first four = 100, so the last two add to 80. x + (x + 10) = 80 → x = 35 (the sixth), fifth = 45.", "difficulty": "moderate", "source": "SSC CGL"},
  {"id": "quant-average-31", "question": "Five years ago, at their marriage, the average age of a husband and wife was 25 years. Today the average age of the couple and their child is 21 years. How old is the child?", "options": ["1 year", "5 years", "13 years", "3 years"], "answer": 3, "explanation": "Couple's total then = 50, now = 60. Family total now = 21 × 3 = 63, so the child is 63 − 60 = 3 years. Forgetting the 5 years gives 13.", "difficulty": "moderate", "source": "SSC CGL"},
  {"id": "quant-average-32", "question": "The average mark of a class of 40 students is 63. The average of those who passed is 75 and of those who failed is 45. How many students passed?", "options": ["16", "20", "24", "26"], "answer": 2, "explanation": "75p + 45(40 − p) = 40 × 63 = 2,520 → 30p = 720 → p = 24. 16 is the number who failed.", "difficulty": "hard", "source": "SSC CGL"},
  {"id": "quant-average-33", "question": "The average age of 10 boys is 15 years. Two boys aged 12 and 14 leave and three new boys join, making the average 15.5 years. What is the average age of the new boys?", "options": ["15 years", "15.5 years", "16 years", "14.5 years"], "answer": 1, "explanation": "Old total 150, minus 26 = 124 for 8 boys. New total = 11 × 15.5 = 170.5, so the three new boys total 46.5, average 15.5 years.", "difficulty": "hard", "source": "SSC CGL Tier-2"},
  {"id": "quant-average-34", "question": "A batsman's average after 20 innings is 42. How many runs must he score in the 21st innings to raise his average by 2?", "options": ["84", "44", "82", "86"], "answer": 0, "explanation": "New total needed = 21 × 44 = 924; present total = 20 × 42 = 840. Runs needed = 924 − 840 = 84.", "difficulty": "hard", "source": "SSC CGL"},
  {"id": "quant-average-35", "question": "The average weight of 30 students is 50 kg. Five students whose average weight is 60 kg leave, and five new students join; the class average falls by 1 kg. What is the average weight of the new students?", "options": ["55 kg", "59 kg", "49 kg", "54 kg"], "answer": 3, "explanation": "Total 1,500 − 300 = 1,200 for 25. New total = 30 × 49 = 1,470, so the five new students weigh 270 kg, average 54 kg. 55 kg treats the fall as 1 kg per newcomer only.", "difficulty": "very-hard", "source": "SSC CGL Tier-2"},
  {"id": "quant-average-36", "question": "The average of a and b is 25, of b and c is 28, and of c and a is 31. What is the largest of the three numbers?", "options": ["31", "28", "34", "22"], "answer": 2, "explanation": "a + b = 50, b + c = 56, c + a = 62. Adding: 2(a + b + c) = 168 → sum = 84. c = 84 − 50 = 34, a = 28, b = 22. The largest is 34.", "difficulty": "very-hard", "source": "SSC CGL"},
  {"id": "quant-average-37", "question": "The average age of an 11-member team is A years. The captain is 28 and the wicket-keeper is 3 years older. If these two are excluded, the average of the rest is 1 year less than A. What is A?", "options": ["24 years", "25 years", "26 years", "23 years"], "answer": 1, "explanation": "11A − (28 + 31) = 9(A − 1) → 11A − 59 = 9A − 9 → 2A = 50 → A = 25 years.", "difficulty": "very-hard", "source": "SSC CGL Tier-2"},
  {"id": "quant-average-38", "question": "A man's average monthly spending is ₹2,750 for the first 4 months, ₹2,940 for the next 3 months and ₹3,130 for the last 5 months of a year. If he saves ₹24,530 in the year, what is his average monthly income?", "options": ["₹5,000", "₹4,940", "₹4,820", "₹5,200"], "answer": 0, "explanation": "Spending = 4×2,750 + 3×2,940 + 5×3,130 = 11,000 + 8,820 + 15,650 = 35,470. Income = 35,470 + 24,530 = 60,000, so ₹5,000 a month.", "difficulty": "very-hard", "source": "SSC CGL Tier-2"},
  {"id": "quant-average-39", "question": "What is the average of the first 25 odd natural numbers?", "options": ["26", "25", "50", "24"], "answer": 1, "explanation": "The sum of the first n odd numbers is n², so the average is n²/n = n = 25.", "difficulty": "easy", "source": "RRB NTPC · SSC CGL"},
  {"id": "quant-average-40", "question": "The average of four numbers is 15. Three of them are 12, 18 and 10. What is the fourth number?", "options": ["20", "18", "15", "25"], "answer": 0, "explanation": "Total = 4 × 15 = 60, so the fourth = 60 − 40 = 20.", "difficulty": "easy", "source": "RRB NTPC · SSC CGL"},
  {"id": "quant-average-41", "question": "What is the average of all the multiples of 7 between 1 and 100?", "options": ["52.5", "50.5", "56", "49"], "answer": 0, "explanation": "The multiples 7, 14, …, 98 form an AP, so the average = (7 + 98)/2 = 52.5.", "difficulty": "easy", "source": "RRB NTPC · SSC CGL"},
  {"id": "quant-average-42", "question": "The average of 10 consecutive integers is 24.5. What is the largest of them?", "options": ["30", "34", "28", "29"], "answer": 3, "explanation": "For 10 consecutive integers a, …, a + 9 the average is a + 4.5 = 24.5, so a = 20 and the largest is 29.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-average-43", "question": "A grocer mixes 3 kg of rice costing ₹40 per kg with 5 kg costing ₹56 per kg. What is the average cost per kg of the mixture?", "options": ["₹48", "₹46", "₹52", "₹50"], "answer": 3, "explanation": "Weighted average = (3 × 40 + 5 × 56)/8 = (120 + 280)/8 = ₹50. ₹48 is the simple average, which ignores the quantities.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-average-44", "question": "The average of 30 numbers is 40. If each number is doubled and then 5 is subtracted from it, what is the new average?", "options": ["70", "75", "35", "80"], "answer": 1, "explanation": "Every value becomes 2x − 5, so the average becomes 2 × 40 − 5 = 75.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-average-45", "question": "Four years ago the average age of a family of 5 was 24 years. A baby has since been born, and the average age of the 6 members today is 23.5 years. How old is the baby?", "options": ["6 months", "1 year", "2 years", "3 years"], "answer": 1, "explanation": "The 5 members' total age today = 5 × 28 = 140. The 6 members' total = 6 × 23.5 = 141, so the baby is 1 year old. Forgetting the 4 years gives a 21-year error.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-average-46", "question": "The average of three numbers is 44. The first is three times the third and the second is twice the third. What is the largest number?", "options": ["60", "72", "66", "44"], "answer": 2, "explanation": "With third = x: 3x + 2x + x = 6x = 132, so x = 22 and the largest is 3x = 66.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-average-47", "question": "In a class the boys average 72 marks and the girls average 80, and the class average is 75. What is the ratio of boys to girls?", "options": ["1 : 1", "3 : 5", "8 : 5", "5 : 3"], "answer": 3, "explanation": "By alligation, boys : girls = (80 − 75) : (75 − 72) = 5 : 3. Check: (5 × 72 + 3 × 80)/8 = 75.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-average-48", "question": "The average salary of all the workers in a workshop is ₹8,000. The average salary of the 7 technicians is ₹12,000 and that of the rest is ₹6,000. How many workers are there in all?", "options": ["28", "14", "21", "18"], "answer": 2, "explanation": "7 × 12,000 + 6,000(n − 7) = 8,000n gives 84,000 − 42,000 = 2,000n, so n = 21. (Technicians are ₹4,000 above the mean, the others ₹2,000 below, so others = 2 × 7 = 14.)", "difficulty": "hard", "source": "SSC CGL · IBPS PO"},
  {"id": "quant-average-49", "question": "A batsman's average over 40 innings is 50. His highest score exceeds his lowest by 172. Excluding these two innings, his average is 48. What is his highest score?", "options": ["172", "186", "176", "174"], "answer": 3, "explanation": "Total = 2,000; the other 38 innings total 1,824, so highest + lowest = 176. With highest − lowest = 172, highest = (176 + 172)/2 = 174.", "difficulty": "hard", "source": "SSC CGL · IBPS PO"},
  {"id": "quant-average-50", "question": "The average age of A, B and C is 30 years. After 5 years the average age of B and C will be 33 years. What is A's present age?", "options": ["36 years", "24 years", "34 years", "29 years"], "answer": 2, "explanation": "A + B + C = 90. In 5 years B + C + 10 = 66, so B + C = 56 and A = 34. Forgetting to remove the 10 years gives 24.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-average-51", "question": "The average temperature from Monday to Wednesday is 37°C and from Tuesday to Thursday is 34°C. Thursday's temperature is 4/5 of Monday's. What is Thursday's temperature?", "options": ["45°C", "32°C", "36°C", "40°C"], "answer": 2, "explanation": "Mon − Thu = 3 × 37 − 3 × 34 = 9, and Thu = 0.8 Mon, so 0.2 Mon = 9: Mon = 45°C and Thu = 36°C. 45°C is Monday's.", "difficulty": "hard", "source": "SSC CGL · IBPS PO"},
  {"id": "quant-average-52", "question": "The average of 7 consecutive integers is n. If the next 3 consecutive integers are also included, by how much does the average increase?", "options": ["1", "2", "1.5", "3"], "answer": 2, "explanation": "The 7 integers a, …, a + 6 average a + 3; the 10 integers a, …, a + 9 average a + 4.5. The increase is 1.5, whatever n is.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-average-53", "question": "The average height of 35 students was found to be 160 cm. Later it was found that one height was recorded as 144 cm instead of 104 cm and another as 150 cm instead of 155 cm. What is the correct average?", "options": ["158.86 cm", "159 cm", "160.14 cm", "161 cm"], "answer": 1, "explanation": "The recorded total was 40 too high from the first error and 5 too low from the second, a net excess of 35. Correct average = 160 − 35/35 = 159 cm.", "difficulty": "hard", "source": "SSC CGL · IBPS PO"},
  {"id": "quant-average-54", "question": "What is the average of the squares of the first 10 natural numbers?", "options": ["30.25", "36.5", "38.5", "55"], "answer": 2, "explanation": "Sum of squares = n(n + 1)(2n + 1)/6 = 10 × 11 × 21/6 = 385, so the average is 38.5. 30.25 = 5.5² squares the average instead.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-average-55", "question": "A batsman's average after 25 innings is 40. What average must he score over the next 5 innings to have an average of 42 after 30 innings?", "options": ["52", "50", "54", "44"], "answer": 0, "explanation": "He needs 30 × 42 = 1,260 runs and has 1,000, so the next 5 innings need 260 runs, an average of 52.", "difficulty": "hard", "source": "SSC CGL · IBPS PO"},
  {"id": "quant-average-56", "question": "The average of four consecutive odd numbers is 24. What is the product of the smallest and the largest?", "options": ["567", "525", "575", "621"], "answer": 0, "explanation": "The numbers are 21, 23, 25 and 27 (average of the middle two = 24), so the product is 21 × 27 = 567.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-average-57", "question": "How many of the following statements are correct?\n1. The average of the first n odd numbers is n.\n2. The average of the first n even numbers is n + 1.\n3. If every value is multiplied by 3 and then 4 is added, the average becomes 3A + 4.\n4. If groups of 10 and 30 people average 50 and 70, the combined average is 60.", "options": ["Only two", "Only three", "Only one", "All four"], "answer": 1, "explanation": "1, 2 and 3 are true (n²/n = n; n(n + 1)/n = n + 1). 4 is false: (500 + 2,100)/40 = 65, not the simple average 60.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id": "quant-average-58", "question": "Sections A, B and C of a class average 60, 70 and 80 marks. The combined average of A and B is 66, and that of B and C is 75. What is the average of all three sections together?", "options": ["71.5", "72", "70", "71.25"], "answer": 3, "explanation": "A : B = (70 − 66) : (66 − 60) = 2 : 3 and B : C = (80 − 75) : (75 − 70) = 1 : 1, so A : B : C = 2 : 3 : 3. Average = (120 + 210 + 240)/8 = 71.25.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "quant-average-59", "question": "A car runs for 2 hours at 60 km/h, then covers 150 km at 50 km/h, and finally runs for 1 hour at 90 km/h. What is its average speed for the whole journey?", "options": ["66 2/3 km/h", "62.5 km/h", "60 km/h", "58 km/h"], "answer": 2, "explanation": "Distance = 120 + 150 + 90 = 360 km; time = 2 + 3 + 1 = 6 hours; average = 60 km/h. Averaging the three speeds (66 2/3) ignores the different times.", "difficulty": "very-hard", "source": "SSC CGL · IBPS PO"},
  {"id": "quant-average-60", "question": "The average mark of a class of 50 is 62. The top 10 students average 80 and the bottom 10 average 40. What is the average of the remaining 30 students?", "options": ["65", "62", "60", "63 1/3"], "answer": 3, "explanation": "Total = 3,100; the top and bottom groups total 800 + 400 = 1,200, so the middle 30 total 1,900 and average 63 1/3.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "quant-average-61", "question": "What is the average of all three-digit numbers that are divisible by 6?", "options": ["550", "549", "548", "551"], "answer": 1, "explanation": "They run from 102 to 996 in an AP, so the average is (102 + 996)/2 = 549.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id": "quant-average-62", "question": "A batsman averages 40 runs over 3 innings. In the 4th innings his average rises by 5, and in the 5th innings it falls by 4. How many runs did he score in the 5th innings?", "options": ["41", "25", "36", "60"], "answer": 1, "explanation": "After 4 innings: 4 × 45 = 180, so the 4th innings = 180 − 120 = 60. After 5 innings: 5 × 41 = 205, so the 5th innings = 205 − 180 = 25.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "quant-average-63", "question": "Assertion (A): If every number in a set is increased by 5, the average increases by 5.\nReason (R): The sum of the numbers increases by 5n, where n is the number of values.", "options": ["A is false but R is true", "A is true but R is false", "Both A and R are true, but R is not the correct explanation of A", "Both A and R are true, and R is the correct explanation of A"], "answer": 3, "explanation": "New average = (S + 5n)/n = S/n + 5, so A follows directly from R.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id": "quant-average-64", "question": "The average weight of A, B and C is 60 kg. When D joins them the average becomes 62 kg. E, who weighs 4 kg more than D, then replaces A, and the average of B, C, D and E becomes 64 kg. What is A's weight?", "options": ["64 kg", "72 kg", "68 kg", "60 kg"], "answer": 0, "explanation": "A + B + C = 180; adding D gives 248, so D = 68 and E = 72. B + C + D + E = 256 gives B + C = 116, so A = 180 − 116 = 64 kg.", "difficulty": "very-hard", "source": "SSC CGL · IBPS PO"},
  {"id": "quant-average-65", "question": "An employee's average monthly salary over a year is ₹33,000. His salary was raised by 20% after the first 6 months. What was his salary in the first 6 months?", "options": ["₹30,000", "₹27,500", "₹30,500", "₹31,500"], "answer": 0, "explanation": "6x + 6(1.2x) = 13.2x = 12 × 33,000 = 3,96,000, so x = ₹30,000. ₹27,500 assumes the raise applied all year.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "quant-average-66", "question": "The average of 5 distinct positive integers is 20. What is the largest possible value of the greatest of them?", "options": ["94", "90", "96", "80"], "answer": 1, "explanation": "The sum is 100; to make one number as large as possible the other four should be the smallest distinct positive integers 1, 2, 3, 4 (sum 10), leaving 90. 96 forgets the numbers must be distinct.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id": "quant-average-67", "question": "The average age of a group is 40 years. When 5 people with an average age of 46 leave and 3 people with an average age of 30 join, the average becomes 38 years. How many people were in the group originally?", "options": ["32", "35", "28", "30"], "answer": 0, "explanation": "40n − 230 + 90 = 38(n − 2) gives 40n − 140 = 38n − 76, so n = 32. Check: (1,280 − 140)/30 = 38.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "quant-average-68", "question": "The average mark of 40 students in a test is 56, which includes 4 absent students who were given 0. The 4 later take a re-test and score an average of 75. What is the new class average?", "options": ["63.5", "65.5", "62.2", "61.4"], "answer": 0, "explanation": "Old total = 2,240. Adding 4 × 75 = 300 gives 2,540, so the new average = 2,540/40 = 63.5.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id":"quant-average-69","question":"What is the average of 48, 56, 63, 71 and 82?","options":["63","64","65","66"],"answer":1,"explanation":"Sum = 320, and 320 ÷ 5 = 64. Quick check: deviations from 64 are −16, −8, −1, +7, +18, which add to 0.","difficulty":"easy","source":"SSC CHSL · RRB Group D"},
  {"id":"quant-average-70","question":"What is the average of the first 15 multiples of 4?","options":["32","30","34","60"],"answer":0,"explanation":"Average of 4, 8, …, 60 = 4 × average of 1 to 15 = 4 × 8 = 32.","difficulty":"easy","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-average-71","question":"If the average of x, x + 2, x + 4, x + 6 and x + 8 is 30, what is x?","options":["30","22","28","26"],"answer":3,"explanation":"For equally spaced numbers the average is the middle term, x + 4 = 30, so x = 26.","difficulty":"easy","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-average-72","question":"A bowler concedes 6, 9, 4, 11 and 10 runs in his five overs. What is his economy rate (average runs per over)?","options":["7.5","8.5","8","40"],"answer":2,"explanation":"Total = 40 runs in 5 overs, so 40 ÷ 5 = 8 runs per over.","difficulty":"easy","source":"RRB Group D · SSC CHSL"},
  {"id":"quant-average-73","question":"What is the average of all the prime numbers between 10 and 30?","options":["19","20","18.67","17.5"],"answer":2,"explanation":"Primes: 11, 13, 17, 19, 23, 29. Sum = 112, and 112 ÷ 6 ≈ 18.67.","difficulty":"easy","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-average-74","question":"What is the average of 0.5, 1.5, 2.5, …, 9.5?","options":["4.5","5","5.5","10"],"answer":1,"explanation":"An arithmetic sequence averages (first + last)/2 = (0.5 + 9.5)/2 = 5.","difficulty":"easy","source":"RRB Group D · SSC CHSL"},
  {"id":"quant-average-75","question":"By how much does the average of the first 8 multiples of 9 exceed the average of the first 8 multiples of 6?","options":["13.5","27","4.5","3"],"answer":0,"explanation":"Average of the first 8 multiples of k = k × 4.5. So 9 × 4.5 − 6 × 4.5 = 3 × 4.5 = 13.5.","difficulty":"easy","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-average-76","question":"A shop's average daily sale from Monday to Saturday is ₹12,000, and on Sunday it sells ₹19,000. What is its average daily sale for the week?","options":["₹15,500","₹12,500","₹13,500","₹13,000"],"answer":3,"explanation":"Week's sales = 6 × 12,000 + 19,000 = ₹91,000. Average = 91,000 ÷ 7 = ₹13,000.","difficulty":"moderate","source":"SSC CHSL · IBPS Clerk"},
  {"id":"quant-average-77","question":"The average age of four sisters is 15 years. Without the eldest, the average of the other three is 13 years. How old is the eldest?","options":["19 years","17 years","23 years","21 years"],"answer":3,"explanation":"Eldest = 4 × 15 − 3 × 13 = 60 − 39 = 21 years.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-average-78","question":"A student averages 64 marks in 5 subjects. How much must he score in the sixth subject to raise his average to 66?","options":["66","70","76","72"],"answer":2,"explanation":"Needed total = 6 × 66 = 396; present total = 320. Sixth subject = 76. Shortcut: 66 + 5 × 2 = 76.","difficulty":"moderate","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-average-79","question":"The average age of a cricket team of 11 is 26 years. If the 32-year-old captain is left out, what is the average age of the rest?","options":["25 years","25.4 years","25.6 years","26.6 years"],"answer":1,"explanation":"Total = 286; without the captain, 254 over 10 players = 25.4 years. Shortcut: the captain is 6 above average, so the others drop by 6/10.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-average-80","question":"The average of 20 numbers is zero. At most how many of them can be greater than zero?","options":["19","10","20","0"],"answer":0,"explanation":"The sum must be 0, so at least one number must be negative (or all zero). Nineteen can be positive if the twentieth is a large enough negative number.","difficulty":"moderate","source":"SSC CGL · CDS"},
  {"id":"quant-average-81","question":"The average weight of 10 parcels is 4.5 kg. If the heaviest (9 kg) and the lightest (1 kg) are removed, what is the average of the rest?","options":["4.375 kg","4.5 kg","4.25 kg","4 kg"],"answer":0,"explanation":"Total = 45 kg. Removing 10 kg leaves 35 kg for 8 parcels: 35 ÷ 8 = 4.375 kg.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-average-82","question":"The average of four consecutive multiples of 5 is 47.5. What is the largest of them?","options":["50","60","52.5","55"],"answer":3,"explanation":"The four numbers are 40, 45, 50, 55 (centred on 47.5). The largest is 55.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-average-83","question":"The average of 5 numbers is 40. The first two are each increased by 5 and the third is decreased by 10. What is the new average?","options":["42","38","40","41"],"answer":2,"explanation":"Total change = +5 + 5 − 10 = 0, so the average stays 40.","difficulty":"moderate","source":"SSC CHSL · RRB Group D"},
  {"id":"quant-average-84","question":"The average of the first n natural numbers is 25.5. What is n?","options":["51","50","25","52"],"answer":1,"explanation":"The average of 1 to n is (n + 1)/2 = 25.5, so n = 50.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-average-85","question":"A shop's average daily sale over 25 days is ₹8,400. What must its average sale be over the next 5 days to make the 30-day average ₹9,000?","options":["₹9,600","₹12,000","₹10,800","₹11,400"],"answer":1,"explanation":"Needed total = 2,70,000; so far 2,10,000. The last 5 days need ₹60,000, i.e. ₹12,000 a day.","difficulty":"moderate","source":"SSC CHSL · IBPS Clerk"},
  {"id":"quant-average-86","question":"The average of a, b and c is twice b. If b = 6, what is a + c?","options":["30","36","24","18"],"answer":0,"explanation":"a + b + c = 3 × 12 = 36, so a + c = 36 − 6 = 30.","difficulty":"moderate","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-average-87","question":"A batsman scores 540 runs in 14 innings and is not out in 2 of them. What is his batting average (runs per dismissal)?","options":["38.57","40","54","45"],"answer":3,"explanation":"A batting average divides runs by the number of times out: 14 − 2 = 12. So 540 ÷ 12 = 45. Dividing by 14 is the trap.","difficulty":"moderate","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-average-88","question":"A family's average monthly electricity bill over a year is ₹1,850. If the 4 summer months average ₹2,900, what is the average of the other 8 months?","options":["₹1,500","₹800","₹1,325","₹1,375"],"answer":2,"explanation":"Year's total = ₹22,200; summer = ₹11,600. Other 8 months = 10,600 ÷ 8 = ₹1,325.","difficulty":"moderate","source":"SSC CHSL · IBPS Clerk"},
  {"id":"quant-average-89","question":"The average weight of a class is 40 kg. A quarter of the students average 46 kg. What is the average weight of the rest?","options":["34 kg","37 kg","38 kg","39 kg"],"answer":2,"explanation":"0.25 × 46 + 0.75 × x = 40 gives 0.75x = 28.5, so x = 38 kg. (A quarter 6 kg above means the rest are 2 kg below.)","difficulty":"moderate","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-average-90","question":"The average of four numbers is 60, and the first is one-fourth of the sum of the other three. What is the first number?","options":["60","48","40","45"],"answer":1,"explanation":"Total = 240. If the first is a, then a = (240 − a)/4, so 5a = 240 and a = 48.","difficulty":"moderate","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-average-91","question":"The average weight of 5 boxes is 24 kg. Two boxes averaging 30 kg are removed and three boxes averaging 18 kg are added. What is the new average?","options":["19 kg","20 kg","21 kg","18 kg"],"answer":0,"explanation":"New total = 120 − 60 + 54 = 114 kg for 6 boxes, so the average = 19 kg.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-average-92","question":"The average of five numbers is 18. If 3, 6, 9, 12 and 15 are added to them respectively, what is the new average?","options":["21","45","30","27"],"answer":3,"explanation":"The additions average 9, so the new average = 18 + 9 = 27.","difficulty":"moderate","source":"SSC CHSL · RRB Group D"},
  {"id":"quant-average-93","question":"The average age of a family of 5 is 24 years. If the three children average 12 years, what is the average age of the parents?","options":["36 years","40 years","44 years","42 years"],"answer":3,"explanation":"Family total = 120; children = 36. Parents = 84, so their average = 42 years.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-average-94","question":"By how much does the average of the first 50 multiples of 7 exceed the average of the first 50 multiples of 5?","options":["2","25.5","51","102"],"answer":2,"explanation":"Average of the first 50 multiples of k = 25.5k. Difference = 25.5 × 2 = 51.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-average-95","question":"A vendor buys 3 dozen bananas at ₹48 a dozen and 2 dozen at ₹60 a dozen. What is the average cost of one banana?","options":["₹4.50","₹4.40","₹4.80","₹4.20"],"answer":1,"explanation":"Cost = 144 + 120 = ₹264 for 60 bananas, so ₹4.40 each. The simple average of ₹4 and ₹5 (₹4.50) ignores the quantities.","difficulty":"moderate","source":"SSC CHSL · RRB Group D"},
  {"id":"quant-average-96","question":"A student's average in 8 tests is 72. If his lowest score, 51, is dropped, what is his average in the remaining tests?","options":["75","74","76","73"],"answer":0,"explanation":"Total = 576. Dropping 51 leaves 525 over 7 tests = 75.","difficulty":"moderate","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-average-97","question":"The average of 8 numbers is 14 and the average of 6 of them is 16. The other two numbers are equal. What is each of them?","options":["8","12","10","16"],"answer":0,"explanation":"Total = 112; the six add to 96. The other two add to 16, so each is 8.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-average-98","question":"The average price of 20 pens in a box is ₹12. Five of them cost ₹18 each. What is the average price of the rest?","options":["₹9","₹11","₹8","₹10"],"answer":3,"explanation":"Total = ₹240; five pens cost ₹90. The other 15 cost ₹150, an average of ₹10.","difficulty":"moderate","source":"SSC CHSL · RRB Group D"},
  {"id":"quant-average-99","question":"Four years ago, the average age of a husband, his wife and their child was 30 years. Six years ago, the average age of the wife and the child was 22 years. How old is the husband now?","options":["42 years","40 years","50 years","46 years"],"answer":3,"explanation":"Present total of all three = 90 + 12 = 102. Present total of wife and child = 44 + 12 = 56. Husband = 102 − 56 = 46 years.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-average-100","question":"A bowler has taken 20 wickets at an average of 24.5 runs per wicket. In the next match he takes 4 wickets for 26 runs. What is his new bowling average?","options":["23.8","25.1","21.5","22"],"answer":2,"explanation":"Runs conceded = 490 + 26 = 516 for 24 wickets: 516 ÷ 24 = 21.5.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-average-101","question":"The average mark of a class is 70. Boys make up 40% of the class and average 64. What is the girls' average?","options":["76","74","72","73"],"answer":1,"explanation":"0.4 × 64 + 0.6 × g = 70 gives 0.6g = 44.4, so g = 74.","difficulty":"hard","source":"SSC CGL · IBPS Clerk"},
  {"id":"quant-average-102","question":"When 4 new members whose average weight is 55 kg join a group of 16, the group's average weight rises by 1 kg. What was the original average?","options":["50 kg","54 kg","51 kg","45 kg"],"answer":0,"explanation":"16A + 220 = 20(A + 1) gives 4A = 200, so A = 50 kg. Check: the 4 newcomers are 5 kg above 50, an excess of 20 kg, which lifts all 20 members by 1 kg.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-average-103","question":"A student's average in 3 tests is 72. To have an average of 75 after 4 tests and 77 after 5 tests, what must he score in the fifth test?","options":["85","84","80","87"],"answer":0,"explanation":"After 4 tests the total must be 300; after 5 tests, 385. So the fifth test needs 385 − 300 = 85.","difficulty":"hard","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-average-104","question":"An athlete's average lap time over 7 laps is 76 seconds. What must his 8th lap time be to bring the 8-lap average down to 75 seconds?","options":["74 s","75 s","69 s","68 s"],"answer":3,"explanation":"Needed total = 600 s; current total = 532 s. The 8th lap must take 68 s (75 − 7 × 1).","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-average-105","question":"What is the average of the numbers from 1 to 20 after all the perfect squares are removed?","options":["10.5","11","11.25","12.25"],"answer":2,"explanation":"Sum 1 to 20 = 210. Squares 1, 4, 9, 16 add to 30, leaving 180 over 16 numbers: 11.25.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-average-106","question":"What is the average of all two-digit numbers whose digits add up to 9?","options":["49.5","54","45","63"],"answer":1,"explanation":"They are 18, 27, …, 90 — an arithmetic sequence with step 9. Average = (18 + 90)/2 = 54.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-average-107","question":"Six numbers are in arithmetic progression with common difference 4, and their average is 25. What is the largest?","options":["33","35","37","29"],"answer":1,"explanation":"The average of an AP is the middle value; the largest is 2.5 steps above it: 25 + 2.5 × 4 = 35.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-average-108","question":"An office has 24 employees with an average age of 36. Four employees with an average age of 60 retire, and four new employees with an average age of 24 join. What is the new average age?","options":["30 years","33 years","36 years","31.5 years"],"answer":0,"explanation":"The total falls by 4 × (60 − 24) = 144, so the average falls by 144/24 = 6 years: 36 − 6 = 30.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-average-109","question":"The average height of 39 students is 150 cm. The tallest student (170 cm) leaves and two new students of 148 cm and 152 cm join. What is the new average height?","options":["150 cm","149 cm","150.5 cm","149.5 cm"],"answer":3,"explanation":"New total = 5,850 − 170 + 300 = 5,980 cm for 40 students: 149.5 cm.","difficulty":"hard","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-average-110","question":"The average of a set of numbers is 40. If 20% of the numbers are each increased by 10 and 30% of them are each decreased by 5, what is the new average?","options":["41","39.5","40.5","42"],"answer":2,"explanation":"Change in average = 0.2 × 10 − 0.3 × 5 = 2 − 1.5 = +0.5. New average = 40.5.","difficulty":"hard","source":"SSC CGL · SSC CPO"},
  {"id":"quant-average-111","question":"The average weight of a class of 45 is 52 kg. If the 5 heaviest students, whose average is 70 kg, are left out, by how much does the average fall?","options":["2 kg","2.5 kg","2.25 kg","18 kg"],"answer":2,"explanation":"Remaining total = 2,340 − 350 = 1,990 kg for 40 students = 49.75 kg. Fall = 2.25 kg. Shortcut: 5 × (70 − 52)/40 = 2.25.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-average-112","question":"The arithmetic mean of two numbers is 25 and their geometric mean is 20. What is the larger number?","options":["30","40","45","35"],"answer":1,"explanation":"a + b = 50 and ab = 400. The numbers are roots of t² − 50t + 400 = 0, i.e. 40 and 10.","difficulty":"hard","source":"SSC CGL · CDS"},
  {"id":"quant-average-113","question":"A car runs 240 km on a highway at 16 km per litre and 360 km in the city at 20 km per litre. What is its average mileage for the whole trip?","options":["18.18 km/l","18 km/l","18.4 km/l","17.5 km/l"],"answer":0,"explanation":"Fuel used = 15 + 18 = 33 L for 600 km: 600/33 ≈ 18.18 km/l. Averaging 16 and 20 (or weighting by distance, 18.4) ignores the litres actually used.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-average-114","question":"In a one-day match a team scores at 4.2 runs per over in the first 15 overs. What run rate does it need in the remaining 35 overs to reach 308?","options":["6.16","7.2","6.5","7"],"answer":3,"explanation":"Runs so far = 63. Needed = 245 in 35 overs, i.e. 7 runs per over.","difficulty":"hard","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-average-115","question":"A company's 120 employees have an average salary of ₹48,000. Men average ₹52,000 and women ₹42,000. How many women are there?","options":["72","60","40","48"],"answer":3,"explanation":"Alligation: women : men = (52 − 48) : (48 − 42) = 4 : 6. Women = 4/10 × 120 = 48.","difficulty":"hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-average-116","question":"The average of 12 numbers is 40. When two of them are removed, the average of the rest rises by 2. What is the average of the two numbers removed?","options":["35","50","30","28"],"answer":2,"explanation":"Total = 480; the 10 remaining add to 10 × 42 = 420. The two removed add to 60, an average of 30.","difficulty":"hard","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-average-117","question":"The average of x numbers is y² and the average of y numbers is x². What is the average of all the numbers together?","options":["x + y","xy","(x² + y²)/2","x²y²"],"answer":1,"explanation":"Total = x·y² + y·x² = xy(x + y), spread over x + y numbers. Average = xy.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS"},
  {"id":"quant-average-118","question":"Class A averages 55 marks and class B averages 65. One student moves from B to A, and the averages of both classes go up. What must be true of that student's marks?","options":["Between 55 and 65","Above 65","Below 55","Exactly 60"],"answer":0,"explanation":"B's average rises only if the student scored below 65; A's rises only if he scored above 55. So the score lies strictly between 55 and 65.","difficulty":"very-hard","source":"SSC CGL · CAT-style"},
  {"id":"quant-average-119","question":"A batsman's average is 48. He scores 0 in his next innings and his average falls by 2. He then scores 100 in the following innings. What is his average now?","options":["48.16","48","50","47.92"],"answer":0,"explanation":"48n = 46(n + 1) gives n = 23, so he had 1,104 runs. After 0 and 100: 1,204 runs in 25 innings = 48.16.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-average-120","question":"Seven distinct positive integers have an average of 10 and a median of 12. What is the largest possible value of the greatest of them?","options":["49","31","28","25"],"answer":3,"explanation":"Sum = 70. Make the rest as small as possible: 1, 2, 3 below the median, 12, then 13, 14 above. Greatest = 70 − 45 = 25.","difficulty":"very-hard","source":"SSC CGL · CAT-style"},
  {"id":"quant-average-121","question":"Ten years ago the average age of a family of 4 was 32 years. Two children have since been born, and the average age of the family of 6 is now 30 years. If the children differ in age by 2 years, how old is the younger child?","options":["6 years","7 years","5 years","4 years"],"answer":2,"explanation":"The four members now total 128 + 40 = 168. The family of 6 totals 180, so the children total 12: ages 5 and 7.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-average-122","question":"What is the average of all three-digit numbers whose digits are all odd?","options":["550","555","500","545"],"answer":1,"explanation":"Each digit is equally likely to be 1, 3, 5, 7 or 9, so each place averages 5. The average number is 555.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CAT-style"},
  {"id":"quant-average-123","question":"What is the average of all four-digit palindromes (numbers like 3443 that read the same both ways)?","options":["5005","5500","4950","5050"],"answer":1,"explanation":"A palindrome abba = 1001a + 110b. a averages 5 (1 to 9) and b averages 4.5 (0 to 9): 5,005 + 495 = 5,500.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CAT-style"},
  {"id":"quant-average-124","question":"A student's four semesters carry 20, 25, 25 and 30 credits, with grade points 7.2, 7.8, 8.4 and x. If his credit-weighted CGPA is 8.1, what is x?","options":["8.7","9.0","8.4","8.9"],"answer":0,"explanation":"Weighted total = 8.1 × 100 = 810. Known part = 144 + 195 + 210 = 549. So 30x = 261 and x = 8.7.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"quant-average-125","question":"A joint family of 8 has an average age of 30 years. Two years later, a member then aged 62 dies and a baby is born the same day. What is the family's average age just after that?","options":["24 years","30 years","26.25 years","24.25 years"],"answer":3,"explanation":"Two years later the 8 members total 240 + 16 = 256. Replacing the 62-year-old by a newborn: 256 − 62 = 194, and 194 ÷ 8 = 24.25 years.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-average-126","question":"The average of 10 two-digit numbers goes up by 3.6 when the digits of one of them are reversed. By how much do the digits of that number differ?","options":["3.6","36","4","6"],"answer":2,"explanation":"The total rises by 36. Reversing ab changes it by 9(b − a), so 9(b − a) = 36 and the digits differ by 4.","difficulty":"very-hard","source":"SSC CGL · SSC CPO"},
  {"id":"quant-average-127","question":"The average age of 30 students is 15 years. Including the teacher, the average rises by 1 year; including the principal as well, it rises by another year. How old is the principal?","options":["46 years","47 years","48 years","50 years"],"answer":2,"explanation":"With the teacher: 31 × 16 = 496, so the teacher is 46. With the principal too: 32 × 17 = 544, so the principal is 544 − 496 = 48.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-average-128","question":"In a company, managers average ₹80,000 a month and other staff ₹30,000, and the overall average is ₹40,000. What is the ratio of managers to other staff?","options":["4 : 1","1 : 4","3 : 5","1 : 3"],"answer":1,"explanation":"Alligation: managers : others = (40 − 30) : (80 − 40) = 10 : 40 = 1 : 4.","difficulty":"very-hard","source":"IBPS PO · SBI PO"},
  {"id":"quant-average-129","question":"A class has 25 boys averaging 62 marks and 20 girls averaging 71. Five boys averaging 50 are moved to another section. What is the new class average?","options":["68","66","66.5","67"],"answer":0,"explanation":"Total = 1,550 + 1,420 = 2,970. Removing 250 leaves 2,720 for 40 students: 68.","difficulty":"very-hard","source":"SSC CGL · IBPS Clerk"},
  {"id":"quant-average-130","question":"A student averages 70 in 6 subjects. Leaving out his best subject, the average is 66; leaving out his worst, it is 72. By how much does his best score exceed his worst?","options":["6","24","36","30"],"answer":3,"explanation":"Best = 420 − 5 × 66 = 90; worst = 420 − 5 × 72 = 60. Difference = 30.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-average-131","question":"The average score of 30 students is 52. Leaving out the lowest scorer, the average rises to 52.5. What did the lowest scorer get?","options":["51.5","38","22.5","37.5"],"answer":3,"explanation":"Total = 1,560; the other 29 total 29 × 52.5 = 1,522.5. Lowest = 37.5.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-average-132","question":"Petrol costs ₹100, ₹104 and ₹108 a litre in three successive months, and a motorist spends ₹6,000 on petrol every month. What is his average price per litre (to two decimals)?","options":["₹104.00","₹103.50","₹103.90","₹104.10"],"answer":2,"explanation":"Equal spending means the harmonic mean: 3 ÷ (1/100 + 1/104 + 1/108) ≈ ₹103.90. He buys more litres when petrol is cheap, so his average is below ₹104.","difficulty":"very-hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-average-133","question":"What is the average of the first 7 multiples of 11?","options":["38.5","44","48","55"],"answer":1,"explanation":"Average of 11, 22, …, 77 = 11 × average of 1 to 7 = 11 × 4 = 44.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-average-134","question":"The average of five consecutive numbers is 42. What is the average of the first three of them?","options":["41","42","40","43"],"answer":0,"explanation":"The numbers are 40 to 44. The first three, 40, 41, 42, average 41.","difficulty":"moderate","source":"SSC CHSL · RRB Group D"},
  {"id":"quant-average-135","question":"Three numbers average 30 and five other numbers average 38. What is the average of all eight?","options":["34","36","33","35"],"answer":3,"explanation":"Total = 90 + 190 = 280; 280 ÷ 8 = 35. The plain average 34 ignores the group sizes.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-average-136","question":"Six numbers average 12. Each number after the first is 2 more than the one before it. What is the largest?","options":["19","22","17","15"],"answer":2,"explanation":"Equally spaced, so the average sits midway between the 3rd and 4th numbers. The largest is 2.5 steps above: 12 + 5 = 17.","difficulty":"hard","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-average-137","question":"A class has 24 boys averaging 45 kg and 16 girls averaging 40 kg. Four girls averaging 42 kg leave and four boys averaging 50 kg join. What is the new average weight of the class?","options":["43 kg","44.2 kg","43.8 kg","45 kg"],"answer":2,"explanation":"Old total = 1,080 + 640 = 1,720. Change = 4 × (50 − 42) = +32, so 1,752/40 = 43.8 kg.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-average-138","question":"The mean of 20 observations was found to be 15. Later it was found that two values, actually 40 and 8, had been recorded as 4 and 26. What is the correct mean?","options":["15","15.9","16.8","14.1"],"answer":1,"explanation":"Correct total = 300 − 30 + 48 = 318, so the mean is 318/20 = 15.9.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-average-139","question":"The average of a, b, c and d is 18. The average of c and d is 15, and a is 6 more than b. What is a?","options":["24","21","18","27"],"answer":0,"explanation":"a + b = 72 − 30 = 42 and a − b = 6, so a = 24.","difficulty":"moderate","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-average-140","question":"An office of 50 staff has an average salary of ₹30,000. Ten managers averaging ₹40,000 get a 20% raise and everyone else gets a 5% raise. What is the new average salary?","options":["₹32,400","₹33,000","₹31,500","₹32,700"],"answer":3,"explanation":"Managers total ₹4,00,000 (+₹80,000); the other 40 total ₹11,00,000 (+₹55,000). Rise = 1,35,000/50 = ₹2,700, so ₹32,700.","difficulty":"very-hard","source":"IBPS PO · SBI PO"},
  {"id":"quant-average-141","question":"Men earn ₹600 a day and women ₹450 a day on a site where there are twice as many men as women. What is the average daily wage?","options":["₹525","₹500","₹575","₹550"],"answer":3,"explanation":"Weighted average = (2 × 600 + 1 × 450)/3 = ₹550.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-average-142","question":"What is the average of all two-digit numbers that leave a remainder of 2 when divided by 5?","options":["52","55","54.5","57.5"],"answer":2,"explanation":"They are 12, 17, …, 97, an arithmetic sequence. Average = (12 + 97)/2 = 54.5.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-average-143","question":"When one value, 63, in a list is replaced by 98, the average of the list rises by 5. How many values are in the list?","options":["5","7","35","8"],"answer":1,"explanation":"The total rises by 35, which spread over n values is 5, so n = 7.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC"},
];

